// Role-aware tab configuration
// Posts + Media are combined into "Feeds" (id: 'feeds')
// Shop + Tickets are combined into "Shop" (id: 'shop') for teams/businesses/stadiums
function getTabsForRole(role) {
    const feeds = [
        {
            id: 'feeds',
            label: 'Feeds'
        }
    ];
    switch(role){
        case 'team':
            return [
                {
                    id: 'overview',
                    label: 'Overview'
                },
                ...feeds,
                {
                    id: 'squad',
                    label: 'Squad'
                },
                {
                    id: 'shop',
                    label: 'Shop'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
        case 'business':
            return [
                {
                    id: 'overview',
                    label: 'Overview'
                },
                ...feeds,
                {
                    id: 'shop',
                    label: 'Shop'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
        case 'player':
            return [
                {
                    id: 'overview',
                    label: 'Overview'
                },
                ...feeds,
                {
                    id: 'stats',
                    label: 'Stats'
                },
                {
                    id: 'career',
                    label: 'Career'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
        case 'coach':
            return [
                {
                    id: 'overview',
                    label: 'Overview'
                },
                ...feeds,
                {
                    id: 'stats',
                    label: 'Stats'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
        case 'analyst':
            return [
                {
                    id: 'overview',
                    label: 'Overview'
                },
                ...feeds,
                {
                    id: 'tools',
                    label: 'Tools'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
        case 'stadium':
        case 'venue':
            return [
                {
                    id: 'overview',
                    label: 'Overview'
                },
                ...feeds,
                {
                    id: 'facilities',
                    label: 'Facilities'
                },
                {
                    id: 'shop',
                    label: 'Shop'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
        case 'journalist':
            return [
                {
                    id: 'overview',
                    label: 'Overview'
                },
                ...feeds,
                {
                    id: 'articles',
                    label: 'Articles'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
        case 'creator':
            return [
                {
                    id: 'overview',
                    label: 'Overview'
                },
                ...feeds,
                {
                    id: 'spotlight',
                    label: 'Spotlight'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
        default:
            return [
                ...feeds,
                {
                    id: 'spotlight',
                    label: 'Spotlight'
                },
                {
                    id: 'about',
                    label: 'About'
                }
            ];
    }
}
